import type MarkdownIt from 'markdown-it';

// `markdown-it`'s `export =` shape means its `MarkdownIt.StateBlock` namespace
// type isn't reachable through the default import (same note as in
// `details-plugin.ts` / `preview.ts`). Derive it from the instance shape.
type StateBlock = InstanceType<MarkdownIt['block']['State']>;
type BlockRule = (
  state: StateBlock,
  startLine: number,
  endLine: number,
  silent: boolean,
) => boolean;

const DASH = 0x2d; /* - */
const EQUALS = 0x3d; /* = */

// ASCII whitespace trimmed by markdown-it's own `asciiTrim` (space, \t, \n, \v,
// \f, \r). Re-created here so we don't reach into a private markdown-it export.
const ASCII_TRIM_RE =
  /^[\x09\x0a\x0b\x0c\x0d\x20]+|[\x09\x0a\x0b\x0c\x0d\x20]+$/g;
function asciiTrim(str: string): string {
  return str.replace(ASCII_TRIM_RE, '');
}

/**
 * Is the given line an *empty* bullet marker (`-`, `*`, `+` followed only by
 * whitespace) sitting at or beyond the current block indent? That is exactly the
 * shape CommonMark refuses to let interrupt a paragraph, and the shape whose `-`
 * variant `lheading` otherwise swallows as a setext underline.
 */
function isEmptyBulletLine(state: StateBlock, line: number): boolean {
  if (state.sCount[line] < state.blkIndent) return false;

  let pos = state.bMarks[line] + state.tShift[line];
  const max = state.eMarks[line];
  if (pos >= max) return false;

  const marker = state.src.charCodeAt(pos);
  if (marker !== DASH && marker !== 0x2a /* * */ && marker !== 0x2b /* + */) {
    return false;
  }
  pos += 1;

  // A bullet marker is a marker char followed by whitespace or end-of-line.
  if (pos < max && !isSpaceOrTab(state.src.charCodeAt(pos))) return false;

  // Empty item: nothing but whitespace after the marker.
  return state.skipSpaces(pos) >= max;
}

function isSpaceOrTab(code: number): boolean {
  return code === 0x20 || code === 0x09;
}

/**
 * A drop-in replacement for markdown-it's `lheading` (setext heading) rule that
 * declines to treat a **lone single `-`** as a setext underline. That single
 * dash is the shape of an empty bullet (`-` / `- `), so letting `lheading` claim
 * it is what turns
 *
 *   - 1
 *     -
 *
 * into `<li><h2>1</h2></li>` (issue #517). Multi-dash `---` underlines and `=`
 * underlines are untouched, so ordinary setext headings still work.
 *
 * Mirrors the upstream rule (markdown-it 14.x `rules_block/lheading.mjs`) with a
 * single added guard on the dash run length.
 */
const lheadingRule: BlockRule = (state, startLine, endLine) => {
  const terminatorRules = state.md.block.ruler.getRules('paragraph');

  // if it's indented more than 3 spaces, it should be a code block
  if (state.sCount[startLine] - state.blkIndent >= 4) return false;

  const oldParentType = state.parentType;
  state.parentType = 'paragraph'; // use paragraph to match terminatorRules

  let level = 0;
  let marker = 0;
  let nextLine = startLine + 1;

  for (; nextLine < endLine && !state.isEmpty(nextLine); nextLine++) {
    // this would be a code block normally, but after paragraph it's considered
    // a lazy continuation regardless of what's there
    if (state.sCount[nextLine] - state.blkIndent > 3) continue;

    // Check for an underline in a setext header.
    if (state.sCount[nextLine] >= state.blkIndent) {
      let pos = state.bMarks[nextLine] + state.tShift[nextLine];
      const max = state.eMarks[nextLine];

      if (pos < max) {
        marker = state.src.charCodeAt(pos);

        if (marker === DASH || marker === EQUALS) {
          const markerStart = pos;
          pos = state.skipChars(pos, marker);
          const runLength = pos - markerStart;
          pos = state.skipSpaces(pos);

          // #517: a lone single `-` is an empty bullet, not a setext underline.
          // Fall through so the paragraph terminates here and the list rule can
          // start the (empty) nested item instead.
          const isLoneDash = marker === DASH && runLength === 1;

          if (pos >= max && !isLoneDash) {
            level = marker === EQUALS ? 1 : 2;
            break;
          }
        }
      }
    }

    // quirk for blockquotes, this line should already be checked by that rule
    if (state.sCount[nextLine] < 0) continue;

    // Some tags can terminate a paragraph without an empty line.
    let terminate = false;
    for (let i = 0, l = terminatorRules.length; i < l; i++) {
      if (terminatorRules[i](state, nextLine, endLine, true)) {
        terminate = true;
        break;
      }
    }
    if (terminate) break;
  }

  if (!level) {
    state.parentType = oldParentType;
    return false;
  }

  const content = asciiTrim(
    state.getLines(startLine, nextLine, state.blkIndent, false),
  );

  state.line = nextLine + 1;

  const tokenOpen = state.push('heading_open', 'h' + String(level), 1);
  tokenOpen.markup = String.fromCharCode(marker);
  tokenOpen.map = [startLine, state.line];

  const tokenInline = state.push('inline', '', 0);
  tokenInline.content = content;
  tokenInline.map = [startLine, state.line - 1];
  tokenInline.children = [];

  const tokenClose = state.push('heading_close', 'h' + String(level), -1);
  tokenClose.markup = String.fromCharCode(marker);

  state.parentType = oldParentType;

  return true;
};

/**
 * markdown-it plugin (notes preview only) that makes a **lone empty bullet**
 * render as a nested list item instead of accidentally styling the line above it
 * as a Header 2 (issue #517).
 *
 * Two upstream CommonMark guards conspire to produce the `<h2>`:
 *
 *  1. `lheading` treats the lone `-` as a setext heading underline for the
 *     paragraph above it — replaced above so a single dash no longer qualifies.
 *  2. `list` refuses to let an *empty* bullet interrupt a paragraph (it would
 *     otherwise become lazy `1<br>-` text) — relaxed below so, in
 *     paragraph-terminator (silent) mode, an empty bullet ends the paragraph and
 *     the normal non-silent list machinery then builds the empty nested item.
 *
 * This is a deliberate, notes-scoped deviation from CommonMark toward the more
 * intuitive editing behavior. See docs/design/notes/notes.md.
 */
export function listEmptyBulletPlugin(md: MarkdownIt): void {
  md.block.ruler.at('lheading', lheadingRule);

  // Grab the current `list` rule so we can delegate to it for every case other
  // than the empty-bullet-interrupts-a-paragraph one.
  const originalList = getRuleFn(md, 'list');

  const wrappedList: BlockRule = (state, startLine, endLine, silent) => {
    if (
      silent &&
      state.parentType === 'paragraph' &&
      isEmptyBulletLine(state, startLine)
    ) {
      // Signal that this empty bullet terminates the paragraph. The paragraph
      // rule stops here; the list rule then runs non-silently on this line,
      // where the empty-item guard does not apply, and builds the nested list.
      return true;
    }
    return originalList(state, startLine, endLine, silent);
  };

  // `Ruler.at` replaces the rule's `alt` chain, so restore `list`'s original
  // paragraph/reference/blockquote membership or it stops terminating them.
  md.block.ruler.at('list', wrappedList, {
    alt: ['paragraph', 'reference', 'blockquote'],
  });
}

/**
 * Read a block rule's current function by name. markdown-it's Ruler exposes no
 * public getter, so we read its private `__rules__` registry (each entry pairs a
 * rule `name` with its `fn`). Used to delegate to the stock `list` rule.
 */
function getRuleFn(md: MarkdownIt, name: string): BlockRule {
  const ruler = md.block.ruler as unknown as {
    __rules__: Array<{ name: string; fn: BlockRule; enabled: boolean }>;
  };
  const rule = ruler.__rules__.find((r) => r.name === name);
  if (!rule) throw new Error(`markdown-it block rule not found: ${name}`);
  return rule.fn;
}

import MarkdownIt from 'markdown-it';
// `highlight.js/lib/common` (~35 commonly fenced languages: js/ts, python,
// bash, go, rust, java/c/c++/c#, ruby, php, sql, yaml, json, markdown, xml,
// css, etc.) instead of the full `highlight.js` package, which statically
// registers all ~190 bundled languages and would blow the frontend's
// per-chunk size budget (see harness.config.json `chunkBudgets`) for a
// notes-preview feature that only ever highlights one fence at a time.
import hljs from 'highlight.js/lib/common';
import taskLists from 'markdown-it-task-lists';
import katexPlugin from '@vscode/markdown-it-katex';
import { detailsPlugin } from './details-plugin.js';
import { listEmptyBulletPlugin } from './list-empty-bullet-plugin.js';

const md: MarkdownIt = new MarkdownIt({
  html: false,
  linkify: true,
  // Soft line breaks (single newline -> <br>), matching CodePair's behavior.
  breaks: true,
  highlight(str, lang) {
    if (lang && hljs.getLanguage(lang)) {
      try {
        return hljs.highlight(str, { language: lang, ignoreIllegals: true })
          .value;
      } catch {
        // Fall through: render as an unhighlighted, escaped code block.
      }
    }
    // Empty string signals "no highlighting" to our custom fence renderer
    // below, which falls back to escaping the raw content itself.
    return '';
  },
});

// Read-only task-list checkboxes (`- [ ] foo` / `- [x] foo`): the preview is
// not editable, so checkboxes render disabled rather than interactive.
md.use(taskLists, { label: true, enabled: false });

// KaTeX math (`$inline$` and `$$block$$`).
md.use(katexPlugin);

// Collapsible sections (`<details>` / `<summary>`). A narrow allowlist for
// just these two disclosure tags — keeps the preview's `html: false` posture
// (no arbitrary raw HTML) while supporting GitHub/MDN-style foldouts.
md.use(detailsPlugin);

// A lone empty bullet under a list item should nest as an empty child, not turn
// the line above it into a setext `<h2>` (issue #517).
md.use(listEmptyBulletPlugin);

/**
 * Code fences: reuses markdown-it's own `highlight` option (configured
 * above) but renders the block ourselves so we can guarantee the `hljs`
 * class (for the syntax palette in notes-preview.css) and inject a copy
 * button, matching CodePair's code-block affordances.
 *
 * The copy button is a child of a non-scrolling outer wrapper, NOT of the
 * `<pre>`: the `<pre>` is the horizontally-scrolling element, so anchoring
 * the button to it would make the button drift out of view when a long line
 * scrolls the block sideways. The wrapper is the positioning context; the
 * `<pre>` only owns overflow.
 */
md.renderer.rules.fence = (tokens, idx, options) => {
  const token = tokens[idx];
  const info = token.info ? md.utils.unescapeAll(token.info).trim() : '';
  const lang = info.split(/\s+/)[0] || '';
  const highlighted = options.highlight
    ? options.highlight(token.content, lang, '') ||
      md.utils.escapeHtml(token.content)
    : md.utils.escapeHtml(token.content);
  const langClass = lang ? ` language-${md.utils.escapeHtml(lang)}` : '';

  return (
    `<div class="note-code-wrapper">` +
    `<button class="note-copy-btn" type="button" aria-label="Copy code">Copy</button>` +
    `<pre class="hljs note-code">` +
    `<code class="hljs${langClass}">${highlighted}</code>` +
    `</pre>` +
    `</div>\n`
  );
};

// `markdown-it`'s default export is a synthesized-default `export =` class,
// so its merged `MarkdownIt.Renderer.RenderRule` namespace type isn't
// reachable through the value import above; derive the render-rule type
// from the (statically typed) `rules` record instead.
type RenderRule = NonNullable<typeof md.renderer.rules.fence>;

const defaultRenderToken: RenderRule = (tokens, idx, options, _env, self) =>
  self.renderToken(tokens, idx, options);

// External links (`http://` / `https://`) open in a new tab without handing
// the new page a `window.opener` reference back into the note.
const defaultLinkOpen = md.renderer.rules.link_open ?? defaultRenderToken;
md.renderer.rules.link_open = (tokens, idx, options, env, self) => {
  const token = tokens[idx];
  const href = token.attrGet('href');
  if (href && /^https?:\/\//.test(href)) {
    token.attrSet('target', '_blank');
    token.attrSet('rel', 'noopener noreferrer');
  }
  return defaultLinkOpen(tokens, idx, options, env, self);
};

// Images load lazily and don't block the main thread while decoding.
const defaultImageRule = md.renderer.rules.image ?? defaultRenderToken;
md.renderer.rules.image = (tokens, idx, options, env, self) => {
  const token = tokens[idx];
  token.attrSet('loading', 'lazy');
  token.attrSet('decoding', 'async');
  return defaultImageRule(tokens, idx, options, env, self);
};

const COPY_BUTTON_SELECTOR = '.note-copy-btn';
const COPY_RESET_DELAY_MS = 1500;

/**
 * A lightweight, framework-free markdown preview pane. Renders `markdown-it`
 * HTML into a container element on demand.
 *
 * SECURITY: `html: false` is deliberate. Enabling raw inline HTML in a
 * collaborator's note is a stored-XSS vector (any workspace member could
 * embed `<script>`/event-handler HTML that runs in another member's
 * session), so this preview never renders raw HTML from note content. This
 * is an intentional deviation from CodePair, which used `html: true` plus a
 * sanitizer step; Wafflebase opts to never construct the sanitize-or-be-
 * vulnerable trade-off in the first place.
 */
export class NotePreview {
  readonly el: HTMLDivElement;

  constructor() {
    this.el = document.createElement('div');
    this.el.dataset.role = 'note-preview';
    this.el.className = 'note-preview markdown-body';

    // One delegated listener survives `render()`'s innerHTML replacement, so
    // copy buttons work without per-render listener churn/leaks.
    this.el.addEventListener('click', (e) => {
      const target = e.target;
      if (!(target instanceof Element)) return;
      const button = target.closest(COPY_BUTTON_SELECTOR);
      if (!(button instanceof HTMLElement) || !this.el.contains(button)) return;

      const code = button.parentElement?.querySelector('code');
      const text = code?.textContent ?? '';
      if (!navigator.clipboard?.writeText) return;

      navigator.clipboard
        .writeText(text)
        .then(() => {
          const original = button.textContent;
          button.textContent = 'Copied';
          setTimeout(() => {
            button.textContent = original;
          }, COPY_RESET_DELAY_MS);
        })
        .catch(() => {
          // Clipboard write can fail (permissions, insecure context); the
          // button simply stays as "Copy" and the user can select manually.
        });
    });
  }

  render(markdown: string): void {
    this.el.innerHTML = md.render(markdown);
  }
}

import {
  indentWithTab,
  redo,
  redoDepth,
  undo,
  undoDepth,
} from '@codemirror/commands';
import { markdown } from '@codemirror/lang-markdown';
import { Compartment, EditorState, Prec, type Extension } from '@codemirror/state';
import { EditorView, keymap } from '@codemirror/view';
import { vim } from '@replit/codemirror-vim';
import { basicSetup } from '@uiw/codemirror-extensions-basic-setup';
import { xcodeDark, xcodeLight } from '@uiw/codemirror-theme-xcode';
import type { NoteStore } from '../store/store.js';
import { noteStoreFacet, noteSync } from './note-sync.js';
import {
  noteRemoteSelections,
  noteRemoteSelectionsTheme,
} from './remote-selection.js';
import { NotePreview } from './preview.js';
import {
  computeActiveFormats,
  toggleBold,
  toggleItalic,
  toggleStrikethrough,
  toggleLink,
  insertTable,
  type NoteInlineFormats,
} from './commands.js';

export type ThemeMode = 'light' | 'dark';

/**
 * Pane layout mode (mirrors CodePair's editor modes):
 * - `edit` — editor only
 * - `both` — editor + preview split
 * - `view` — preview only (reading mode)
 */
export type NoteViewMode = 'edit' | 'both' | 'view';

/** Editor keybinding mode (mirrors CodePair's CodeKeyType). */
export type NoteKeymap = 'default' | 'vim';

/** Public API returned by initialize(). */
export interface NoteEditorAPI {
  /** Current markdown text. */
  getText(): string;
  /** Switch the editor color theme. */
  setTheme(mode: ThemeMode): void;
  /** Switch the pane layout: editor only / split / preview only. */
  setViewMode(mode: NoteViewMode): void;
  /** Current pane layout mode. */
  getViewMode(): NoteViewMode;
  /** Switch the editor keybinding mode (default / vim). */
  setKeymap(mode: NoteKeymap): void;
  /** Current editor keybinding mode. */
  getKeymap(): NoteKeymap;
  /** Toggle `**bold**` around the selection. */
  toggleBold(): void;
  /** Toggle `*italic*` around the selection. */
  toggleItalic(): void;
  /** Toggle `~~strikethrough~~` around the selection. */
  toggleStrikethrough(): void;
  /** Wrap the selection as a `[text](url)` link, or unwrap the link at cursor. */
  toggleLink(): void;
  /** Insert a `rows`×`cols` markdown table skeleton at the cursor. */
  insertTable(rows: number, cols: number): void;
  /** Undo the last local edit. */
  undo(): void;
  /** Redo the last undone local edit. */
  redo(): void;
  /** Whether there is a local edit to undo. */
  canUndo(): boolean;
  /** Whether there is an undone local edit to redo. */
  canRedo(): boolean;
  /** Inline markdown formats active at the current selection. */
  getActiveFormats(): NoteInlineFormats;
  /**
   * Register a callback fired whenever the selection or document changes, with
   * the inline formats now active (drives toolbar toggle highlighting). Only
   * one callback is kept; call with `null` to clear.
   */
  onSelectionChange(cb: ((formats: NoteInlineFormats) => void) | null): void;
  /** Focus the editor. */
  focus(): void;
  /** Tear down the editor and its listeners. */
  dispose(): void;
}

/**
 * Mount a collaborative markdown editor into `container`.
 *
 * Left pane: CodeMirror markdown source, synced to `store` (local edits →
 * store.editText; remote changes → CM transactions). Right pane: live
 * markdown preview re-rendered from the editor content on every change
 * (so both local and remote edits reflect).
 */
export function initialize(
  container: HTMLElement,
  store: NoteStore,
  theme: ThemeMode = 'light',
  readOnly = false,
  viewMode: NoteViewMode = 'both',
): NoteEditorAPI {
  container.style.display = 'flex';
  container.style.alignItems = 'stretch';
  container.style.height = '100%';

  const editorEl = document.createElement('div');
  editorEl.dataset.role = 'note-editor';
  editorEl.style.flex = '1 1 50%';
  // The CodeMirror `.cm-scroller` owns scrolling (see the theme below); keep
  // this wrapper clipped so there is no double scrollbar.
  editorEl.style.overflow = 'hidden';
  editorEl.style.minWidth = '0';

  const preview = new NotePreview();
  preview.el.style.flex = '1 1 50%';
  preview.el.style.overflow = 'auto';
  // Vertical padding matters: `prose` zeroes the first child's margin-top
  // (.note-preview > :first-child), so a first-line heading would otherwise
  // sit flush against the top edge.
  preview.el.style.padding = '16px 20px';
  preview.el.style.minWidth = '0';

  // Draggable divider between the editor and preview (split mode only), so the
  // user can adjust the two panes' widths — the native equivalent of CodePair's
  // react-resizable-layout splitter.
  const divider = document.createElement('div');
  divider.dataset.role = 'note-divider';
  divider.style.flex = '0 0 auto';
  divider.style.width = '7px';
  divider.style.cursor = 'col-resize';
  divider.style.alignSelf = 'stretch';
  divider.style.background = 'var(--border, rgba(0,0,0,0.08))';
  divider.style.backgroundClip = 'content-box';
  divider.style.padding = '0 3px';
  divider.style.userSelect = 'none';
  divider.setAttribute('role', 'separator');
  divider.setAttribute('aria-orientation', 'vertical');

  container.appendChild(editorEl);
  container.appendChild(divider);
  container.appendChild(preview.el);

  const themeExt = (mode: ThemeMode) =>
    mode === 'light' ? xcodeLight : xcodeDark;

  const currentDoc = () => view.state.doc.toString();
  const renderPreview = () => preview.render(currentDoc());

  // Notifies the host (toolbar) of the active inline formats as the selection
  // or document changes, so it can highlight the format toggles.
  let selectionCb: ((formats: NoteInlineFormats) => void) | null = null;

  // Editor keybinding mode; `vim()` must sit at the front of the extension
  // list (before the default keymaps) to take precedence.
  let currentKeymap: NoteKeymap = 'default';

  // Compartments so theme / keymap switches reconfigure in place instead of
  // rebuilding the whole EditorState — a full rebuild would drop the undo
  // history (basicSetup's history()), silently disabling undo after a toggle.
  const themeCompartment = new Compartment();
  const keymapCompartment = new Compartment();

  const keymapExt = (): Extension => {
    // CodeMirror deliberately leaves Tab out of the default keymap (so keyboard
    // users can tab out of the editor). Bind it explicitly for indent/outdent.
    // @replit/codemirror-vim binds no Tab key and lets it fall through (it only
    // preventDefaults keys it actually handles), so indentWithTab drives Tab
    // indent in both modes; `vim()` sits ahead of it so vim still wins for every
    // key it does handle.
    if (currentKeymap === 'vim') {
      return [vim(), keymap.of([indentWithTab])];
    }
    return [
      keymap.of([indentWithTab]),
      // Escape releases the Tab-indent focus trap (WCAG 2.1.2): with Tab bound
      // to indent it no longer moves focus out, so give keyboard users an
      // explicit exit. Low precedence so autocomplete / tooltip Escape handlers
      // still win first; only blurs when nothing else consumes Escape. (Vim owns
      // Escape itself, so this is default-mode only.)
      Prec.low(
        keymap.of([
          {
            key: 'Escape',
            run: (v) => {
              v.contentDOM.blur();
              return true;
            },
          },
        ]),
      ),
    ];
  };

  const buildExtensions = (mode: ThemeMode): Extension[] => [
    keymapCompartment.of(keymapExt()),
    basicSetup({ highlightSelectionMatches: false }),
    markdown(),
    themeCompartment.of(themeExt(mode)),
    EditorView.lineWrapping,
    EditorView.editable.of(!readOnly),
    // Fill the wrapper's full height (so an empty note starts full-height, not
    // collapsed to one line) and let the internal scroller handle overflow.
    EditorView.theme({
      '&': { width: '100%', height: '100%' },
      '.cm-scroller': { overflow: 'auto' },
    }),
    EditorView.updateListener.of((u) => {
      if (u.docChanged) renderPreview();
      if (u.docChanged || u.selectionSet) {
        selectionCb?.(computeActiveFormats(u.state));
      }
    }),
    noteStoreFacet.of(store),
    noteSync,
    noteRemoteSelectionsTheme,
    noteRemoteSelections,
  ];

  const state = EditorState.create({
    doc: store.getText(),
    extensions: buildExtensions(theme),
  });

  const view = new EditorView({ state, parent: editorEl });
  renderPreview();

  let currentTheme = theme;

  // Toggle which panes are visible for the current layout mode. The preview
  // still receives updates while hidden (the updateListener fires regardless
  // of display), so switching into it shows current content; we re-render and
  // re-measure the editor defensively on show.
  let currentViewMode: NoteViewMode = viewMode;
  let splitRatio = 0.5; // editor's share of the width in split mode
  const applyViewMode = (mode: NoteViewMode) => {
    currentViewMode = mode;
    const showEditor = mode !== 'view';
    const showPreview = mode !== 'edit';
    const split = showEditor && showPreview;
    editorEl.style.display = showEditor ? '' : 'none';
    preview.el.style.display = showPreview ? '' : 'none';
    divider.style.display = split ? '' : 'none';
    if (split) {
      editorEl.style.flex = `1 1 ${(splitRatio * 100).toFixed(3)}%`;
      preview.el.style.flex = `1 1 ${((1 - splitRatio) * 100).toFixed(3)}%`;
    } else {
      editorEl.style.flex = showEditor ? '1 1 100%' : '0 0 0';
      preview.el.style.flex = showPreview ? '1 1 100%' : '0 0 0';
    }
    if (showPreview) renderPreview();
    if (showEditor) view.requestMeasure();
  };
  applyViewMode(viewMode);

  // Divider drag: adjust splitRatio from the pointer x within the container.
  // `endDrag` is set while a drag is in flight so dispose() can tear down the
  // window listeners if the editor unmounts mid-drag.
  let endDrag: (() => void) | null = null;
  const onDividerPointerDown = (e: PointerEvent) => {
    if (currentViewMode !== 'both') return;
    e.preventDefault();
    const rect = container.getBoundingClientRect();
    const onMove = (ev: PointerEvent) => {
      const ratio = (ev.clientX - rect.left) / rect.width;
      splitRatio = Math.max(0.15, Math.min(0.85, ratio));
      editorEl.style.flex = `1 1 ${(splitRatio * 100).toFixed(3)}%`;
      preview.el.style.flex = `1 1 ${((1 - splitRatio) * 100).toFixed(3)}%`;
    };
    const onUp = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      document.body.style.removeProperty('cursor');
      document.body.style.removeProperty('user-select');
      endDrag = null;
      view.requestMeasure();
    };
    endDrag = onUp;
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };
  divider.addEventListener('pointerdown', onDividerPointerDown);

  // Proportional scroll sync between the editor scroller and the preview,
  // active only in split ('both') mode. Mirrors CodePair's react-scroll-sync,
  // which syncs by scroll percentage (not source-line mapping) and is on by
  // default. A lock flag suppresses the echo scroll event on the destination.
  const editorScroller = view.scrollDOM;
  let scrollLock = false;
  const scrollRatioOf = (el: HTMLElement) => {
    const range = el.scrollHeight - el.clientHeight;
    return range > 0 ? el.scrollTop / range : 0;
  };
  const applyScrollRatio = (el: HTMLElement, ratio: number) => {
    const range = el.scrollHeight - el.clientHeight;
    el.scrollTop = ratio * range;
  };
  const linkScroll = (src: HTMLElement, dst: HTMLElement) => () => {
    if (scrollLock || currentViewMode !== 'both') return;
    scrollLock = true;
    applyScrollRatio(dst, scrollRatioOf(src));
    requestAnimationFrame(() => {
      scrollLock = false;
    });
  };
  const onEditorScroll = linkScroll(editorScroller, preview.el);
  const onPreviewScroll = linkScroll(preview.el, editorScroller);
  editorScroller.addEventListener('scroll', onEditorScroll, { passive: true });
  preview.el.addEventListener('scroll', onPreviewScroll, { passive: true });

  return {
    getText: () => view.state.doc.toString(),
    setTheme: (mode: ThemeMode) => {
      if (mode === currentTheme) return;
      currentTheme = mode;
      // Reconfigure the theme compartment in place; a full state rebuild would
      // discard the undo history (see the compartment comment above).
      view.dispatch({
        effects: themeCompartment.reconfigure(themeExt(mode)),
      });
    },
    setViewMode: (mode: NoteViewMode) => {
      if (mode === currentViewMode) return;
      applyViewMode(mode);
    },
    getViewMode: () => currentViewMode,
    setKeymap: (mode: NoteKeymap) => {
      if (mode === currentKeymap) return;
      currentKeymap = mode;
      // Reconfigure the keymap compartment in place so the undo history (and
      // the current selection) survive a Default <-> Vim switch.
      view.dispatch({
        effects: keymapCompartment.reconfigure(keymapExt()),
      });
      view.focus();
    },
    getKeymap: () => currentKeymap,
    toggleBold: () => toggleBold(view),
    toggleItalic: () => toggleItalic(view),
    toggleStrikethrough: () => toggleStrikethrough(view),
    toggleLink: () => toggleLink(view),
    insertTable: (rows, cols) => insertTable(view, rows, cols),
    undo: () => {
      undo(view);
      view.focus();
    },
    redo: () => {
      redo(view);
      view.focus();
    },
    canUndo: () => undoDepth(view.state) > 0,
    canRedo: () => redoDepth(view.state) > 0,
    getActiveFormats: () => computeActiveFormats(view.state),
    onSelectionChange: (cb) => {
      selectionCb = cb;
    },
    focus: () => view.focus(),
    dispose: () => {
      endDrag?.(); // tear down window listeners if a divider drag is in flight
      editorScroller.removeEventListener('scroll', onEditorScroll);
      preview.el.removeEventListener('scroll', onPreviewScroll);
      divider.removeEventListener('pointerdown', onDividerPointerDown);
      view.destroy();
    },
  };
}

import { describe, it, expect, vi } from 'vitest';
import { NotePreview } from './preview.js';

describe('NotePreview', () => {
  it('highlights fenced code blocks with the hljs class', () => {
    const preview = new NotePreview();
    preview.render('```js\nconst x = 1;\n```');

    const code = preview.el.querySelector('pre.note-code > code');
    expect(code).toBeTruthy();
    expect(code?.className).toContain('hljs');
    expect(code?.className).toContain('language-js');
    // highlight.js should have tokenized the keyword into a span.
    expect(code?.innerHTML).toContain('hljs-keyword');

    // Copy button is present alongside the code.
    expect(preview.el.querySelector('.note-copy-btn')).toBeTruthy();
  });

  it('places the copy button in the wrapper, outside the scrolling <pre>', () => {
    const preview = new NotePreview();
    preview.render('```\ncode\n```');

    const wrapper = preview.el.querySelector('.note-code-wrapper');
    const button = preview.el.querySelector('.note-copy-btn');
    const pre = preview.el.querySelector('pre.note-code');

    // The button anchors to the non-scrolling wrapper so it stays pinned when
    // a long line scrolls the <pre> horizontally, rather than drifting inside
    // the scrolled content.
    expect(wrapper).toBeTruthy();
    expect(button?.parentElement).toBe(wrapper);
    expect(pre?.parentElement).toBe(wrapper);
    expect(pre?.contains(button)).toBe(false);
  });

  it('renders a disabled checkbox for task-list items', () => {
    const preview = new NotePreview();
    preview.render('- [x] done\n- [ ] todo');

    const checkboxes = preview.el.querySelectorAll(
      'input.task-list-item-checkbox',
    );
    expect(checkboxes.length).toBe(2);
    for (const checkbox of checkboxes) {
      expect(checkbox.getAttribute('disabled')).not.toBeNull();
    }
    expect(checkboxes[0].hasAttribute('checked')).toBe(true);
    expect(checkboxes[1].hasAttribute('checked')).toBe(false);
  });

  it('renders KaTeX markup for inline math', () => {
    const preview = new NotePreview();
    preview.render('$E = mc^2$');
    expect(preview.el.querySelector('.katex')).toBeTruthy();
  });

  it('adds target=_blank and rel=noopener to external links', () => {
    const preview = new NotePreview();
    preview.render('[link](https://example.com)');
    const a = preview.el.querySelector('a');
    expect(a?.getAttribute('target')).toBe('_blank');
    expect(a?.getAttribute('rel')).toBe('noopener noreferrer');
  });

  it('adds loading=lazy and decoding=async to images', () => {
    const preview = new NotePreview();
    preview.render('![alt](https://example.com/img.png)');
    const img = preview.el.querySelector('img');
    expect(img?.getAttribute('loading')).toBe('lazy');
    expect(img?.getAttribute('decoding')).toBe('async');
  });

  it('renders a collapsed <details>/<summary> disclosure by default', () => {
    const preview = new NotePreview();
    preview.render(
      '<details>\n<summary>More</summary>\n\nHidden body\n\n</details>',
    );

    const details = preview.el.querySelector('details.note-details');
    const summary = details?.querySelector('summary.note-summary');
    expect(details).toBeTruthy();
    expect(summary?.textContent).toBe('More');
    // Collapsed by default: no `open` attribute.
    expect(details?.hasAttribute('open')).toBe(false);
    // Body markdown is rendered inside the disclosure.
    expect(details?.textContent).toContain('Hidden body');
  });

  it('renders <details open> expanded by default', () => {
    const preview = new NotePreview();
    preview.render(
      '<details open>\n<summary>Peek</summary>\n\nShown\n\n</details>',
    );

    const details = preview.el.querySelector('details.note-details');
    expect(details).toBeTruthy();
    expect(details?.hasAttribute('open')).toBe(true);
  });

  it('renders markdown inside the summary label and the body', () => {
    const preview = new NotePreview();
    preview.render(
      '<details>\n<summary>**bold** label</summary>\n\n- one\n- two\n\n</details>',
    );

    const summary = preview.el.querySelector('summary.note-summary');
    expect(summary?.querySelector('strong')?.textContent).toBe('bold');

    const items = preview.el.querySelectorAll('details.note-details li');
    expect(items.length).toBe(2);
  });

  it('supports nested <details> disclosures', () => {
    const preview = new NotePreview();
    preview.render(
      [
        '<details>',
        '<summary>Outer</summary>',
        '',
        '<details>',
        '<summary>Inner</summary>',
        '',
        'deep',
        '',
        '</details>',
        '',
        '</details>',
      ].join('\n'),
    );

    const outer = preview.el.querySelector('details.note-details');
    const inner = outer?.querySelector('details.note-details');
    expect(outer).toBeTruthy();
    expect(inner).toBeTruthy();
    expect(inner?.textContent).toContain('deep');
  });

  it('does not emit raw HTML for a stray </details> or embedded tags', () => {
    const preview = new NotePreview();
    // No opening <details>: the close must not become an orphan element, and
    // the script tag must never be rendered as executable HTML.
    preview.render('</details>\n\n<script>alert(1)</script>');

    expect(preview.el.querySelector('details')).toBeNull();
    expect(preview.el.querySelector('script')).toBeNull();
    // The literal text is preserved (escaped), proving html:false still holds.
    expect(preview.el.textContent).toContain('<script>alert(1)</script>');
  });

  // Issue #517: a list item followed by an empty nested bullet used to render
  // the parent's text as a setext `<h2>` (the lone `-` was read as an underline).
  it('nests an empty bullet instead of turning the parent into an <h2>', () => {
    const preview = new NotePreview();
    preview.render('- 1\n  -');

    // No accidental heading.
    expect(preview.el.querySelector('h2')).toBeNull();

    // Parent keeps body text and gains an empty nested child item.
    const outer = preview.el.querySelector('ul > li');
    expect(outer?.textContent?.trim().startsWith('1')).toBe(true);
    const nested = outer?.querySelector('ul > li');
    expect(nested).toBeTruthy();
    expect(nested?.textContent?.trim()).toBe('');
  });

  it('nests an empty bullet with a trailing space too', () => {
    const preview = new NotePreview();
    preview.render('- 1\n  - ');
    expect(preview.el.querySelector('h2')).toBeNull();
    expect(preview.el.querySelector('ul > li > ul > li')).toBeTruthy();
  });

  it('still renders the blank-line workaround correctly', () => {
    const preview = new NotePreview();
    preview.render('- 1\n\n  - ');
    expect(preview.el.querySelector('h2')).toBeNull();
    expect(preview.el.querySelector('ul > li > ul > li')).toBeTruthy();
  });

  it('preserves multi-dash setext headings', () => {
    const preview = new NotePreview();
    preview.render('Heading\n---');
    const h2 = preview.el.querySelector('h2');
    expect(h2?.textContent).toBe('Heading');
  });

  it('leaves a non-empty nested list unchanged', () => {
    const preview = new NotePreview();
    preview.render('- 1\n  - 2');
    expect(preview.el.querySelector('h2')).toBeNull();
    const nested = preview.el.querySelector('ul > li > ul > li');
    expect(nested?.textContent?.trim()).toBe('2');
  });

  it('copies code to the clipboard when the copy button is clicked', async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    Object.assign(navigator, { clipboard: { writeText } });

    const preview = new NotePreview();
    document.body.appendChild(preview.el);
    preview.render('```\nhello world\n```');

    const button =
      preview.el.querySelector<HTMLButtonElement>('.note-copy-btn');
    expect(button).toBeTruthy();
    button?.dispatchEvent(new MouseEvent('click', { bubbles: true }));

    // Clipboard write is async; flush microtasks.
    await Promise.resolve();
    await Promise.resolve();

    expect(writeText).toHaveBeenCalledWith('hello world\n');
    expect(button?.textContent).toBe('Copied');

    preview.el.remove();
  });
});
